/* ==========================================================================
   Northbrook University – Course Registration
   All text/background pairs below meet WCAG 2.2 AA (4.5:1 for text,
   3:1 for UI components and focus indicators).
   ========================================================================== */

:root {
  --violet-900: #2e1065;
  --violet-800: #4c1d95;
  --violet-700: #5b21b6;
  --violet-100: #ede9fe;
  --violet-50: #f5f3ff;
  --pink-700: #be185d;
  --pink-100: #fce7f3;
  --orange-700: #c2410c;
  --orange-100: #ffedd5;
  --teal-700: #0f766e;
  --teal-100: #ccfbf1;
  --blue-700: #1d4ed8;
  --blue-100: #dbeafe;
  --green-700: #047857;
  --green-100: #d1fae5;
  --red-700: #b91c1c;
  --red-50: #fef2f2;
  --sun: #fde047;

  --text: #1f2937;
  --text-muted: #4b5563;
  --bg: #faf8ff;
  --surface: #ffffff;
  --border: #6b7280;      /* 4.8:1 on white – meets 3:1 for form controls */
  --border-soft: #ddd6fe;

  --radius: 0.75rem;
  --radius-lg: 1.25rem;
  --shadow: 0 4px 14px rgba(46, 16, 101, 0.1);
  --shadow-lg: 0 18px 40px rgba(46, 16, 101, 0.25);
  --focus-ring: 0 0 0 3px #ffffff, 0 0 0 6px var(--violet-900);
  --max-width: 75rem;
  --font: "Segoe UI", system-ui, -apple-system, Roboto, "Helvetica Neue", Arial, sans-serif;
}

/* ---------- Base ---------- */

*,
*::before,
*::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  font-family: var(--font);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

body:has(dialog[open]) { overflow: hidden; }

main { flex: 1; }
main:focus { outline: none; }

[hidden] { display: none !important; }

h1, h2, h3 { line-height: 1.25; margin: 0 0 0.75rem; color: var(--violet-900); }
h1 { font-size: clamp(1.875rem, 4vw + 1rem, 3rem); }
h2 { font-size: clamp(1.375rem, 1.5vw + 1rem, 1.875rem); }
h3 { font-size: 1.2rem; }

p { margin: 0 0 1rem; }

a { color: var(--violet-700); text-underline-offset: 0.18em; text-decoration-thickness: 1px; }
a:hover { color: var(--pink-700); text-decoration-thickness: 2px; }

img { max-width: 100%; height: auto; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin-inline: auto;
  padding-inline: 1rem;
}

@media (min-width: 48em) {
  .container { padding-inline: 2rem; }
}

/* ---------- Focus indicators (WCAG 2.4.7 / 2.4.11 / 2.4.13) ---------- */

:focus-visible {
  outline: 3px solid var(--violet-900);
  outline-offset: 3px;
  box-shadow: 0 0 0 3px #ffffff;
}

/* On dark backgrounds use a bright yellow ring instead. */
.site-header :focus-visible,
.hero :focus-visible,
.page-banner :focus-visible,
.site-footer :focus-visible {
  outline-color: var(--sun);
  box-shadow: 0 0 0 3px var(--violet-900);
}

/* Elements that only receive programmatic focus still show where focus went. */
[tabindex="-1"]:focus-visible { outline-offset: 4px; }

/* ---------- Utilities ---------- */

.visually-hidden {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -100px;
  z-index: 1000;
  padding: 0.75rem 1.25rem;
  background: var(--sun);
  color: var(--violet-900);
  font-weight: 700;
  border-radius: 0 0 var(--radius) var(--radius);
  text-decoration: none;
}

.skip-link:focus { top: 0; }

/* ---------- Header & navigation ---------- */

.site-header {
  background: linear-gradient(110deg, var(--violet-900) 0%, var(--violet-800) 55%, #831843 100%);
  color: #ffffff;
  position: sticky;
  top: 0;
  z-index: 50;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.25);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
  padding-block: 0.6rem;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  color: #ffffff;
  text-decoration: none;
  font-weight: 700;
  line-height: 1.2;
  border-radius: 0.5rem;
  padding: 0.25rem;
}

.brand:hover { color: #ffffff; }

.brand-mark {
  display: grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 0.75rem;
  background: linear-gradient(135deg, var(--sun), #fb923c);
  color: var(--violet-900);
  font-weight: 800;
  letter-spacing: 0.02em;
}

.brand-sub {
  display: block;
  font-weight: 400;
  font-size: 0.875rem;
  color: #f5f3ff;
}

.primary-nav { display: contents; }

.nav-toggle {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.5rem 1rem;
  font: inherit;
  font-weight: 600;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.12);
  border: 2px solid #ffffff;
  border-radius: 999px;
  cursor: pointer;
}

.nav-toggle-icon,
.nav-toggle-icon::before,
.nav-toggle-icon::after {
  display: block;
  width: 1.1rem;
  height: 2px;
  background: currentColor;
  border-radius: 2px;
  transition: transform 0.2s ease;
}

.nav-toggle-icon { position: relative; }
.nav-toggle-icon::before,
.nav-toggle-icon::after { content: ""; position: absolute; left: 0; }
.nav-toggle-icon::before { top: -6px; }
.nav-toggle-icon::after { top: 6px; }

.nav-toggle[aria-expanded="true"] .nav-toggle-icon { background: transparent; }
.nav-toggle[aria-expanded="true"] .nav-toggle-icon::before { transform: translateY(6px) rotate(45deg); }
.nav-toggle[aria-expanded="true"] .nav-toggle-icon::after { transform: translateY(-6px) rotate(-45deg); }

.nav-menu {
  list-style: none;
  margin: 0;
  padding: 0;
  width: 100%;
}

/* Without JavaScript the menu is always visible and the toggle is hidden. */
html:not(.js) .nav-toggle { display: none; }
.js .nav-menu:not(.is-open) { display: none; }

.nav-menu a {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.6rem 1rem;
  color: #ffffff;
  text-decoration: none;
  font-weight: 600;
  border-radius: 0.6rem;
}

.nav-menu a:hover { background: rgba(255, 255, 255, 0.16); color: #ffffff; }

.nav-menu a[aria-current="page"] {
  background: #ffffff;
  color: var(--violet-800);
}

.nav-badge {
  display: inline-grid;
  place-items: center;
  min-width: 1.5rem;
  height: 1.5rem;
  padding-inline: 0.4rem;
  border-radius: 999px;
  background: var(--sun);
  color: var(--violet-900);
  font-size: 0.8rem;
  font-weight: 800;
}

@media (max-width: 47.99em) {
  .nav-menu.is-open { padding-bottom: 0.5rem; }
  .nav-menu li + li { margin-top: 0.25rem; }
}

@media (min-width: 48em) {
  .primary-nav { display: block; }
  .nav-toggle { display: none !important; }
  .js .nav-menu:not(.is-open),
  .nav-menu {
    display: flex;
    gap: 0.25rem;
    width: auto;
  }
}

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 2.75rem;
  padding: 0.65rem 1.35rem;
  font: inherit;
  font-weight: 700;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  border: 2px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease, box-shadow 0.15s ease;
}

.btn:hover { transform: translateY(-1px); }
.btn:active { transform: translateY(0); }

.btn-primary { background: var(--violet-700); color: #ffffff; }
.btn-primary:hover { background: var(--violet-900); color: #ffffff; }

.btn-secondary { background: #ffffff; color: var(--violet-700); border-color: var(--violet-700); }
.btn-secondary:hover { background: var(--violet-50); color: var(--violet-900); }

.btn-danger { background: var(--red-700); color: #ffffff; }
.btn-danger:hover { background: #7f1d1d; color: #ffffff; }

.btn-sun { background: var(--sun); color: var(--violet-900); }
.btn-sun:hover { background: #facc15; color: var(--violet-900); }

.btn-light { background: #ffffff; color: var(--violet-800); }
.btn-light:hover { background: var(--violet-100); color: var(--violet-900); }

.btn-outline-light { background: transparent; color: #ffffff; border-color: #ffffff; }
.btn-outline-light:hover { background: rgba(255, 255, 255, 0.15); color: #ffffff; }

.btn-small { min-height: 2.25rem; padding: 0.4rem 0.9rem; font-size: 0.9rem; }
.btn-block { width: 100%; }

.icon-btn {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 2.75rem;
  height: 2.75rem;
  font-size: 1.75rem;
  line-height: 1;
  color: var(--violet-900);
  background: var(--violet-100);
  border: 2px solid transparent;
  border-radius: 50%;
  cursor: pointer;
}

.icon-btn:hover { border-color: var(--violet-700); }

/* ---------- Hero (home) ---------- */

.hero {
  background:
    radial-gradient(circle at 85% 15%, rgba(253, 224, 71, 0.25), transparent 35%),
    linear-gradient(120deg, var(--violet-800) 0%, var(--pink-700) 60%, var(--orange-700) 100%);
  color: #ffffff;
  padding-block: clamp(2.5rem, 7vw, 5rem);
}

.hero h1 { color: #ffffff; max-width: 18ch; }

.eyebrow {
  display: inline-block;
  margin-bottom: 1rem;
  padding: 0.3rem 0.9rem;
  border-radius: 999px;
  background: var(--sun);
  color: var(--violet-900);
  font-weight: 700;
  font-size: 0.9rem;
}

.hero-lead { font-size: 1.15rem; max-width: 55ch; }

.hero-search {
  margin-block: 1.75rem;
  max-width: 40rem;
}

.hero-search-label { display: block; font-weight: 700; margin-bottom: 0.4rem; }

.search-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.search-row input { flex: 1 1 14rem; }

.hint-on-dark { color: #ffffff; margin-top: 0.4rem; }

.hero-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; }

/* ---------- Page banners ---------- */

.page-banner {
  color: #ffffff;
  padding-block: clamp(1.75rem, 4vw, 3rem);
}

.page-banner h1 { color: #ffffff; margin-bottom: 0.25rem; }
.page-banner p { margin: 0; font-size: 1.1rem; }

.banner-blue { background: linear-gradient(120deg, var(--blue-700), var(--violet-700) 70%, var(--pink-700)); }
.banner-pink { background: linear-gradient(120deg, var(--pink-700), var(--violet-700) 65%, var(--blue-700)); }
.banner-green { background: linear-gradient(120deg, var(--teal-700), var(--blue-700) 60%, var(--violet-700)); }

/* ---------- Sections ---------- */

.section { padding-block: clamp(2.5rem, 6vw, 4rem); }
.section-tint { background: linear-gradient(180deg, var(--violet-50), var(--pink-100)); }

.steps {
  list-style: none;
  margin: 1.5rem 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  gap: 1.25rem;
}

.step {
  position: relative;
  padding: 1.5rem;
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  border-top: 6px solid var(--accent);
}

.step h3 { color: var(--accent); }
.step p { margin: 0; }

.step-number {
  display: grid;
  place-items: center;
  width: 2.5rem;
  height: 2.5rem;
  margin-bottom: 0.75rem;
  border-radius: 50%;
  background: var(--accent);
  color: #ffffff;
  font-weight: 800;
  font-size: 1.1rem;
}

.step-violet { --accent: var(--violet-700); }
.step-pink { --accent: var(--pink-700); }
.step-orange { --accent: var(--orange-700); }
.step-teal { --accent: var(--teal-700); }

.dept-grid {
  list-style: none;
  margin: 1.5rem 0 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 13rem), 1fr));
  gap: 0.85rem;
}

.dept-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  min-height: 3.5rem;
  padding: 0.85rem 1.1rem;
  border-radius: var(--radius);
  background: var(--dept-color);
  color: #ffffff;
  font-weight: 700;
  text-decoration: none;
  box-shadow: var(--shadow);
  transition: transform 0.15s ease;
}

.dept-link::after { content: "→"; aria-hidden: true; }
.dept-link:hover { color: #ffffff; transform: translateY(-2px); }

.two-col {
  display: grid;
  gap: 2rem;
}

@media (min-width: 56em) {
  .two-col { grid-template-columns: 3fr 2fr; align-items: start; }
}

.date-list { list-style: none; margin: 1rem 0 0; padding: 0; }

.date-list li {
  display: grid;
  gap: 0.15rem;
  padding: 0.9rem 1rem;
  margin-bottom: 0.6rem;
  background: var(--surface);
  border-left: 6px solid var(--orange-700);
  border-radius: 0 var(--radius) var(--radius) 0;
  box-shadow: var(--shadow);
}

.date-list li:nth-child(2) { border-left-color: var(--pink-700); }
.date-list li:nth-child(3) { border-left-color: var(--violet-700); }
.date-list li:nth-child(4) { border-left-color: var(--teal-700); }

.date-list time { font-weight: 700; color: var(--violet-900); }

.callout {
  padding: 1.5rem;
  border-radius: var(--radius-lg);
  background: var(--teal-100);
  border: 2px solid var(--teal-700);
}

.callout h2 { color: #134e4a; }
.callout a { color: #134e4a; font-weight: 600; }

/* ---------- Cards ---------- */

.card {
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: clamp(1.25rem, 3vw, 2rem);
}

/* ---------- Catalog ---------- */

.catalog-layout {
  display: grid;
  gap: 2rem;
  padding-block: 2rem 3rem;
}

@media (min-width: 64em) {
  .catalog-layout { grid-template-columns: 19rem 1fr; align-items: start; }
  .filters-panel { position: sticky; top: 5.5rem; }
}

.filters-panel {
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  padding: 1.5rem;
  border-top: 6px solid var(--blue-700);
}

.filters-panel h2 { font-size: 1.35rem; }

.filter-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
  gap: 0 1rem;
}

@media (min-width: 64em) {
  .filter-grid { grid-template-columns: 1fr; }
}

.results-header {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem 1rem;
  margin-bottom: 1rem;
}

.results-header h2 { margin: 0; }

.results-count {
  margin: 0;
  padding: 0.25rem 0.85rem;
  border-radius: 999px;
  background: var(--blue-100);
  color: #1e3a8a;
  font-weight: 700;
}

.course-grid {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(min(100%, 18rem), 1fr));
  gap: 1.25rem;
}

.course-grid > li { display: flex; }

.course-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  overflow: hidden;
  border: 1px solid var(--border-soft);
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.course-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }

.course-card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem;
  background: var(--dept-color);
  color: #ffffff;
  font-weight: 700;
}

.course-code {
  padding: 0.1rem 0.6rem;
  border-radius: 999px;
  background: #ffffff;
  color: var(--dept-color);
  font-size: 0.95rem;
  letter-spacing: 0.02em;
}

.course-dept { font-size: 0.9rem; text-align: right; }

.course-card-body { padding: 1.25rem; flex: 1; }

.course-card-body h3 { color: var(--text); }

.course-desc { color: var(--text-muted); }

.course-meta { margin: 0 0 1rem; display: grid; gap: 0.35rem; }
.course-meta div { display: grid; grid-template-columns: 6.25rem 1fr; gap: 0.5rem; }
.course-meta dt { font-weight: 700; color: var(--violet-900); }
.course-meta dd { margin: 0; }

.seats-text { margin: 0 0 0.35rem; font-weight: 600; color: var(--green-700); }
.seats-low .seats-text { color: var(--orange-700); }
.seats-full .seats-text { color: var(--red-700); }

.seat-bar {
  height: 0.5rem;
  border-radius: 999px;
  background: #e5e7eb;
  overflow: hidden;
}

.seat-bar span {
  display: block;
  height: 100%;
  background: linear-gradient(90deg, var(--teal-700), var(--green-700));
  border-radius: inherit;
}

.seats-low .seat-bar span { background: linear-gradient(90deg, #ea580c, var(--orange-700)); }
.seats-full .seat-bar span { background: var(--red-700); }

.course-card-footer {
  padding: 1rem 1.25rem 1.25rem;
}

.tag {
  margin: 0;
  padding: 0.6rem 1rem;
  border-radius: 999px;
  text-align: center;
  font-weight: 700;
}

.tag-success { background: var(--green-100); color: #065f46; }
.tag-muted { background: #f3f4f6; color: #374151; }

.empty-state {
  padding: 2rem;
  text-align: center;
  background: var(--surface);
  border: 2px dashed var(--violet-700);
  border-radius: var(--radius-lg);
}

/* ---------- Forms ---------- */

.field { margin-bottom: 1.25rem; }

fieldset { border: 0; margin: 0; padding: 0; min-width: 0; }

label,
legend {
  display: block;
  font-weight: 700;
  color: var(--text);
  margin-bottom: 0.3rem;
}

.hint {
  margin: 0 0 0.4rem;
  font-size: 0.95rem;
  color: var(--text-muted);
}

input[type="text"],
input[type="email"],
input[type="search"],
select,
textarea {
  width: 100%;
  min-height: 2.75rem;
  padding: 0.6rem 0.85rem;
  font: inherit;
  color: var(--text);
  background: #ffffff;
  border: 2px solid var(--border);
  border-radius: 0.6rem;
}

select {
  appearance: none;
  padding-right: 2.5rem;
  background-image: linear-gradient(45deg, transparent 50%, var(--violet-700) 50%),
    linear-gradient(135deg, var(--violet-700) 50%, transparent 50%);
  background-position: calc(100% - 1.2rem) 50%, calc(100% - 0.85rem) 50%;
  background-size: 0.35rem 0.35rem;
  background-repeat: no-repeat;
}

.hero input[type="search"] { border-color: #ffffff; }

input:hover,
select:hover,
textarea:hover { border-color: var(--violet-700); }

input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--violet-900);
  outline-offset: 2px;
  border-color: var(--violet-700);
}

.input-short { max-width: 14rem; }

textarea { resize: vertical; }

.choice {
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  margin-bottom: 0.5rem;
}

.choice input {
  flex-shrink: 0;
  width: 1.5rem;
  height: 1.5rem;
  margin: 0.1rem 0 0;
  accent-color: var(--violet-700);
  cursor: pointer;
}

.choice label { font-weight: 400; margin: 0; cursor: pointer; }

.choice-row { display: flex; flex-wrap: wrap; gap: 0.25rem 1.5rem; }
.choice-row .choice label { font-weight: 600; }

.choice-card {
  padding: 0.9rem 1rem;
  border: 2px solid var(--border-soft);
  border-left: 8px solid var(--dept-color);
  border-radius: var(--radius);
  background: var(--violet-50);
}

.choice-card:has(input:checked) { border-color: var(--violet-700); border-left-color: var(--dept-color); background: #ffffff; }

.choice-title { display: block; font-weight: 700; }
.choice-detail { display: block; font-size: 0.95rem; color: var(--text-muted); }

.course-choices { margin-bottom: 0.75rem; }

.credit-total {
  font-weight: 700;
  color: var(--teal-700);
  padding: 0.5rem 0.85rem;
  background: var(--teal-100);
  border-radius: var(--radius);
}

.credit-total.is-over { color: var(--red-700); background: var(--red-50); }

.req-marker { color: var(--red-700); font-weight: 800; }

/* Errors: icon + text + colour, so colour is never the only cue. */
.field-error {
  margin: 0 0 0.4rem;
  color: var(--red-700);
  font-weight: 700;
}

.field-error:empty { display: none; }

.field-error::before {
  content: "!";
  display: inline-grid;
  place-items: center;
  width: 1.25rem;
  height: 1.25rem;
  margin-right: 0.4rem;
  border-radius: 50%;
  background: var(--red-700);
  color: #ffffff;
  font-size: 0.8rem;
  vertical-align: 0.1em;
}

.has-error > input,
.has-error > select,
.has-error > textarea { border-color: var(--red-700); border-width: 3px; }

.field.has-error,
.form-section.has-error {
  border-left: 5px solid var(--red-700);
  padding-left: 1rem;
}

.error-summary {
  margin-bottom: 1.5rem;
  padding: 1.25rem 1.5rem;
  border: 4px solid var(--red-700);
  border-radius: var(--radius);
  background: var(--red-50);
}

.error-summary h2 { color: var(--red-700); font-size: 1.3rem; }
.error-summary ul { margin: 0; padding-left: 1.25rem; }
.error-summary a { color: var(--red-700); font-weight: 700; }

.form-layout { padding-block: 2rem 3rem; max-width: 52rem; }

.form-section {
  padding-bottom: 1.5rem;
  margin-bottom: 1.5rem;
  border-bottom: 2px solid var(--violet-100);
}

.legend-title {
  display: block;
  font-size: 1.3rem;
  color: var(--violet-900);
  margin-bottom: 0.75rem;
}

.form-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; }

/* ---------- Notices ---------- */

.notice {
  padding: 1rem 1.25rem;
  border-radius: var(--radius);
  margin-bottom: 1.5rem;
  border-left: 6px solid;
}

.notice:empty { display: none; }

.notice-success { background: var(--green-100); border-color: var(--green-700); color: #064e3b; }
.notice-success h2 { color: #064e3b; }
.notice-success a { color: #064e3b; font-weight: 700; }
.notice-info { background: var(--blue-100); border-color: var(--blue-700); color: #1e3a8a; }
.notice-info a { color: #1e3a8a; font-weight: 700; }
.notice-warning { background: var(--orange-100); border-color: var(--orange-700); color: #7c2d12; }

.notice p:last-child { margin-bottom: 0; }

/* ---------- Modal dialog ---------- */

.modal {
  width: min(36rem, calc(100% - 2rem));
  max-height: calc(100% - 2rem);
  padding: 0;
  border: 0;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-lg);
  color: var(--text);
  overflow: auto;
}

.modal::backdrop {
  background: rgba(46, 16, 101, 0.7);
}

.modal-inner {
  padding: 1.5rem;
  border-top: 8px solid var(--pink-700);
}

.modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.modal-header h2 { margin-top: 0.4rem; }

.modal-subtitle { font-size: 1.1rem; margin-top: 1rem; }

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.5rem;
}

.confirm-courses { list-style: none; margin: 0 0 1rem; padding: 0; }

.confirm-courses li {
  display: grid;
  padding: 0.65rem 0.85rem;
  margin-bottom: 0.5rem;
  border-left: 6px solid var(--dept-color);
  background: var(--violet-50);
  border-radius: 0 0.5rem 0.5rem 0;
}

.confirm-courses span { font-size: 0.95rem; color: var(--text-muted); }

@media (prefers-reduced-motion: no-preference) {
  .modal[open] { animation: pop-in 0.2s ease-out; }
}

@keyframes pop-in {
  from { opacity: 0; transform: translateY(12px) scale(0.98); }
  to { opacity: 1; transform: none; }
}

/* ---------- Summary lists ---------- */

.summary-list { margin: 0 0 1rem; display: grid; gap: 0.4rem; }
.summary-list div { display: grid; grid-template-columns: minmax(7rem, auto) 1fr; gap: 0.75rem; }
.summary-list dt { font-weight: 700; color: var(--violet-900); }
.summary-list dd { margin: 0; overflow-wrap: anywhere; }

/* ---------- Profile ---------- */

.profile-layout {
  display: grid;
  gap: 2rem;
  padding-block: 2rem 3rem;
}

@media (min-width: 60em) {
  .profile-layout { grid-template-columns: 22rem 1fr; }
  .schedule-section { grid-column: 1 / -1; }
}

.profile-card { border-top: 6px solid var(--teal-700); }

.profile-head { display: flex; align-items: center; gap: 1rem; margin-bottom: 1rem; }
.profile-head h2 { font-size: 1.1rem; margin: 0; color: var(--text-muted); }
.profile-name { margin: 0; font-size: 1.4rem; font-weight: 800; color: var(--violet-900); }

.avatar {
  display: grid;
  place-items: center;
  flex-shrink: 0;
  width: 4rem;
  height: 4rem;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--pink-700), var(--orange-700));
  color: #ffffff;
  font-size: 1.4rem;
  font-weight: 800;
}

.stats {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 11rem), 1fr));
  gap: 1rem;
  height: 100%;
}

.stat {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 1.5rem;
  border-radius: var(--radius-lg);
  color: #ffffff;
  box-shadow: var(--shadow);
}

.stat-value { font-size: 2.75rem; font-weight: 800; line-height: 1; }
.stat-label { font-weight: 600; margin-top: 0.4rem; }

.stat-violet { background: linear-gradient(135deg, var(--violet-700), var(--violet-900)); }
.stat-pink { background: linear-gradient(135deg, var(--pink-700), #9d174d); }
.stat-teal { background: linear-gradient(135deg, var(--teal-700), #115e59); }

.section-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem 1rem;
  margin-bottom: 1rem;
}

.section-head h2 { margin: 0; }

/* ---------- Data table ---------- */

.table-wrap {
  overflow-x: auto;
  background: var(--surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-soft);
}

.data-table {
  width: 100%;
  min-width: 56rem;
  border-collapse: collapse;
}

.data-table caption {
  text-align: left;
  padding: 1rem 1.25rem;
  font-weight: 800;
  font-size: 1.1rem;
  color: var(--violet-900);
}

.caption-hint {
  display: block;
  font-weight: 400;
  font-size: 0.9rem;
  color: var(--text-muted);
}

.data-table th,
.data-table td {
  padding: 0.75rem 1rem;
  text-align: left;
  vertical-align: top;
  border-bottom: 1px solid #e5e7eb;
}

.data-table thead th {
  background: var(--violet-800);
  color: #ffffff;
  font-weight: 700;
  white-space: nowrap;
}

.data-table tbody tr:nth-child(even) { background: var(--violet-50); }
.data-table tbody tr:hover { background: var(--pink-100); }

.data-table tbody th { font-weight: 700; }

.data-table tfoot th,
.data-table tfoot td {
  background: var(--teal-100);
  color: #134e4a;
  font-weight: 800;
  border-bottom: 0;
}

.sort-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 2.25rem;
  padding: 0.25rem 0.5rem;
  margin: -0.25rem -0.5rem;
  font: inherit;
  font-weight: 700;
  color: #ffffff;
  background: transparent;
  border: 2px solid transparent;
  border-radius: 0.4rem;
  cursor: pointer;
}

.sort-btn:hover { border-color: #ffffff; }

.sort-btn:focus-visible {
  outline-color: var(--sun);
  box-shadow: none;
  outline-offset: 1px;
}

.sort-icon::after { content: "↕"; opacity: 0.85; }
th[aria-sort="ascending"] .sort-icon::after { content: "▲"; opacity: 1; }
th[aria-sort="descending"] .sort-icon::after { content: "▼"; opacity: 1; }

.code-pill {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  background: var(--dept-color);
  color: #ffffff;
  white-space: nowrap;
}

/* ---------- Footer ---------- */

.site-footer {
  background: var(--violet-900);
  color: #ffffff;
  padding-block: 1.75rem;
  margin-top: auto;
}

.footer-inner {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.footer-inner p { margin: 0; }

.footer-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1.25rem;
}

.footer-links a { color: #ffffff; display: inline-block; padding-block: 0.4rem; }
.footer-links a:hover { color: var(--sun); }

/* ---------- Motion & high-contrast preferences ---------- */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
  .btn:hover,
  .course-card:hover,
  .dept-link:hover { transform: none; }
}

@media (forced-colors: active) {
  .btn,
  .nav-badge,
  .tag,
  .code-pill,
  .course-code { border: 2px solid CanvasText; }
  .nav-menu a[aria-current="page"] { text-decoration: underline; text-decoration-thickness: 3px; }
  .seat-bar { border: 1px solid CanvasText; }
  :focus-visible { outline: 3px solid Highlight; }
}

@media print {
  .site-header,
  .site-footer,
  .filters-panel,
  .btn { display: none !important; }
  .table-wrap { overflow: visible; box-shadow: none; }
}

