rep=[
('.dept-link::after { content: "→"; aria-hidden: true; }','.dept-link::after { content: "→" / ""; }'),
('html { -webkit-text-size-adjust: 100%; }','html { -webkit-text-size-adjust: 100%; scroll-padding-top: 6rem; }'),
('''  position: sticky;
  top: 0;
  z-index: 50;
  box-shadow''','''  position: relative;
  z-index: 50;
  box-shadow'''),
('.primary-nav { display: contents; }','.primary-nav { margin-left: auto; }'),
('''@media (max-width: 47.99em) {
  .nav-menu.is-open { padding-bottom: 0.5rem; }
  .nav-menu li + li { margin-top: 0.25rem; }
}''','''@media (max-width: 47.99em) {
  html { scroll-padding-top: 1rem; }
  .nav-menu.is-open {
    position: absolute;
    top: 100%;
    left: 0;
    right: 0;
    padding: 0.5rem 1rem 1rem;
    background: var(--violet-900);
    box-shadow: 0 12px 24px rgba(0, 0, 0, 0.3);
  }
  .nav-menu li + li { margin-top: 0.25rem; }
}'''),
('''@media (min-width: 48em) {
  .primary-nav { display: block; }
  .nav-toggle''','''@media (min-width: 48em) {
  .site-header { position: sticky; top: 0; }
  .nav-toggle'''),
]
for a,b in rep:
    assert a in s, a
    s=s.replace(a,b)
open(p,'w').write(s)
EOF
